package cli

import (
	"fmt"
	"io"
	"strings"

	"github.com/Szmelc-INC/Modern-Shell/internal/store"
	"github.com/Szmelc-INC/Modern-Shell/internal/tui"
)

// The shell scripts are thin: they call `msh __complete <words…>` and the Go side
// (which knows the whole command tree and the live item names) answers with
// "value<TAB>description" lines, or __files__ / __dirs__ for path completion.

const zshCompletion = `#compdef msh
# zsh completion for msh — generated by: msh completion zsh
_msh() {
  local -a lines cands
  local l v d
  lines=("${(@f)$(msh __complete "${(@)words[2,CURRENT]}" 2>/dev/null)}")
  case $lines[1] in
    __files__) _files; return ;;
    __dirs__)  _files -/; return ;;
  esac
  for l in $lines; do
    [[ -z $l ]] && continue
    v=${l%%$'\t'*} d=${l#*$'\t'}
    [[ $d == $l ]] && d=''
    cands+=("${v//:/\\:}:$d")
  done
  _describe -t msh 'msh' cands
}
if [[ ${zsh_eval_context[-1]} == loadautofunc ]]; then
  _msh "$@"
else
  compdef _msh msh
fi
`

const bashCompletion = `# bash completion for msh — generated by: msh completion bash
_msh() {
  local cur=${COMP_WORDS[COMP_CWORD]} out IFS=$'\n'
  out=$(msh __complete "${COMP_WORDS[@]:1:COMP_CWORD}" 2>/dev/null)
  case $out in
    __files__*) COMPREPLY=($(compgen -f -- "$cur")); return ;;
    __dirs__*)  COMPREPLY=($(compgen -d -- "$cur")); return ;;
  esac
  COMPREPLY=($(compgen -W "$(printf '%s\n' "$out" | cut -f1)" -- "$cur"))
}
complete -o default -F _msh msh
`

const fishCompletion = `# fish completion for msh — generated by: msh completion fish
function __msh_complete
    set -l tokens (commandline -opc) (commandline -ct)
    set -l out (msh __complete $tokens[2..-1] 2>/dev/null)
    switch "$out[1]"
        case __files__
            __fish_complete_path (commandline -ct)
        case __dirs__
            __fish_complete_directories (commandline -ct)
        case '*'
            printf '%s\n' $out
    end
end
complete -c msh -f -a '(__msh_complete)'
`

func printCompletion(c *Ctx, root *Command, shell string) error {
	switch shell {
	case "zsh":
		io.WriteString(c.Out, zshCompletion)
	case "bash":
		io.WriteString(c.Out, bashCompletion)
	case "fish":
		io.WriteString(c.Out, fishCompletion)
	default:
		return usageErr("unsupported shell %q (zsh, bash, fish)", shell)
	}
	return nil
}

// completeWords answers `msh __complete w1 w2 … current`.
func completeWords(c *Ctx, root *Command, words []string) []string {
	if len(words) == 0 {
		words = []string{""}
	}
	cur := words[len(words)-1]
	cmd := root
	var prev *Flag
	for _, w := range words[:len(words)-1] {
		if prev != nil {
			prev = nil
			continue
		}
		if strings.HasPrefix(w, "-") {
			prev = findFlag(cmd, strings.TrimLeft(w, "-"))
			if prev != nil && (prev.Arg == "" || strings.Contains(w, "=")) {
				prev = nil
			}
			continue
		}
		if n := cmd.find(w); n != nil {
			cmd = n
		}
	}
	if prev != nil {
		if prev.Long == "tab" {
			return tui.TabNames()
		}
		return nil
	}
	if strings.HasPrefix(cur, "-") {
		var out []string
		for _, f := range append(append([]Flag{}, cmd.Flags...), globalFlags...) {
			out = append(out, "--"+f.Long+"\t"+f.Help)
		}
		return out
	}
	if len(cmd.Sub) > 0 {
		var out []string
		for _, s := range cmd.Sub {
			if !s.Hidden {
				out = append(out, s.Name+"\t"+s.Summary)
			}
		}
		return out
	}
	return candidates(c, cmd.Complete)
}

func findFlag(cmd *Command, name string) *Flag {
	name, _, _ = strings.Cut(name, "=")
	for i := range cmd.Flags {
		if cmd.Flags[i].Long == name || cmd.Flags[i].Short == name {
			return &cmd.Flags[i]
		}
	}
	return nil
}

// candidates returns dynamic completion values for a kind.
func candidates(c *Ctx, kind string) []string {
	var out []string
	switch kind {
	case "addon":
		addons, _ := store.LoadAddons(c.P)
		for _, a := range addons {
			out = append(out, a.Name+"\t"+a.Desc)
		}
	case "alias", "env", "secret":
		mf, err := managedFile(c.P, store.Kind(kind))
		if err == nil {
			for _, it := range mf.Items() {
				out = append(out, it.Name+"\t"+it.Desc)
			}
		}
	case "func":
		fns, _ := store.LoadUserFuncs(c.P)
		for _, f := range fns {
			out = append(out, f.Name+"\t"+f.Desc)
		}
	case "dir":
		dirs, _ := store.ListDirs()
		for _, d := range dirs {
			out = append(out, d.Path)
		}
	case "snapshot":
		snaps, _ := store.ListSnapshots(c.P)
		for i, s := range snaps {
			out = append(out, s.ID+"\t#"+fmt.Sprint(i+1)+" "+s.Created+" "+s.Reason)
		}
	case "shell":
		out = []string{"zsh", "bash", "fish"}
	case "tab":
		out = tui.TabNames()
	case "dirpath":
		out = []string{"__dirs__"}
	case "file":
		out = []string{"__files__"}
	}
	return out
}
